(()=>{const button=document.getElementById('themeToggle');let saved;try{saved=localStorage.getItem('fv-theme');}catch{}let mode=saved==='dark'||saved==='light'?saved:(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');function apply(){document.documentElement.dataset.theme=mode;document.documentElement.style.colorScheme=mode;const ar=document.documentElement.lang==='ar';button.textContent=mode==='dark'?'☀':'☾';const label=mode==='dark'?(ar?'الوضع الفاتح':'Light mode'):(ar?'الوضع الداكن':'Dark mode');button.setAttribute('aria-label',label);button.title=label;button.setAttribute('aria-pressed',String(mode==='dark'));}button.onclick=()=>{mode=mode==='dark'?'light':'dark';try{localStorage.setItem('fv-theme',mode);}catch{}apply();};new MutationObserver(apply).observe(document.documentElement,{attributes:true,attributeFilter:['lang']});apply();})();
